import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"12、【否】 坤下乾上","description":"周易口訣義 - 12、【否】 坤下乾上","frontmatter":{"title":"12、【否】 坤下乾上","description":"周易口訣義 - 12、【否】 坤下乾上"},"headers":[],"relativePath":"classics/koujueyi/014.md","filePath":"classics/koujueyi/014.md"}'),r={name:"classics/koujueyi/014.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_12、【否】-坤下乾上" tabindex="-1">12、【否】 坤下乾上 <a class="header-anchor" href="#_12、【否】-坤下乾上" aria-label="Permalink to “12、【否】 坤下乾上”">​</a></h1><p>彖曰：「否之匪人，不利君子貞，大往小來」，則是天地不交而萬物不通也，上下不交而天下無邦也。內陰而外陽，內柔而外剛，內小人而外君子，小人道長，君子道消也。</p><p>象曰：天地不交，否。君子以儉德闢難，不可榮以祿。</p><p>初六：拔茅茹，以其匯，貞吉亨。</p><p>象曰：拔茅貞吉，志在君也。</p><p>六二：包承，小人吉，大人否，亨。</p><p>象曰：「大人否亨」，不亂群也。</p><p>六三：包羞。象曰：「包羞」，位不當也。</p><p>九四：有命無咎，疇離祉。</p><p>象曰：「有命無咎」，志行也。</p><p>九五：休否，大人吉。其亡其亡，繋於苞桑。</p><p>象曰：大人之吉，位正當也。</p><p>上九：傾否，先否後喜。</p><p>象曰：否終則傾，何可長也。</p><p>解讀</p><p>「否之匪人，不利君子貞」者，否以上下不交，君臣不孚，故為閉塞之義也。當否塞之時，小人道長，非是君子德通之時，故曰「匪人」也。小人侵陵君子，邪道乃興，故不利君子而為正，故曰「不利君子貞」也。象曰：「天地不交，否」者，天氣上，地氣下，二氣不相交通，故曰否閉之象也。「君子以儉德避難，不可榮以祿」者，言君子當否閉之時，不可處寵求安，故以節儉為德，避於小人之難，不可榮其身，食以祿也。</p><p>「初六，拔茅茹，以其匯，貞吉，亨」者，夫柔之為道，必依於剛；弱之為道，必親於強，故獨處須託之以君子。今初六體既柔劣，不事幹進，但以眾類親比於上，既不往謟，守正應上，所以獲正之吉也。</p><p>「六二，包承，小人吉，大人否，亨」者，六二以柔順之質，但施包納，承順於君，故曰「包承」也。處否閉之時，是小人道長，故小人獲吉；大人當否閉之時，雖復小人為亂，但防之以道，遏絕小人，所以獲亨通也，故曰「大人否，亨」也。</p><p>「六三包羞」者，蓋恥辱也。六三以謟媚之身，而為小人之行，所為之事，皆包羞恥故也。</p><p>「九四，有命，無咎，疇離祉」者，夫君子親於小人，則有恥累至焉。今九四若有招命於初，是親於小人，禍咎必至。只為初六修正，不敢為謟，故九四命之則無咎，故曰「有命無咎」。既有招命初六，初六必當受福，故曰「疇離祉」也。疇，初也，謂初六；離，著也；祉，福也，謂九四命之，因此招命，得其福也。</p><p>「九五，休否，大人吉。其亡其亡，繋於苞桑」者，休，美也；處否閉之時，而居尊位，以休美之德，悅諭小人，使小人不妄為非，故曰「休否」也。有斯美德，悅服小人，若非大德之人，拯世之君，即不能獲吉，故曰「大人吉」也。以小人道長之時，恐有危亂及身，故丁寧戒懼，慮其滅亡。再言之者，憂懼之甚，故云「其亡其亡」也。既慮危亂，故必「繋於苞桑」之固矣。苞，本也；桑者根多，固有牢固之義，故曰「繋苞桑」也。</p><p>「上九，傾否，先否後喜」者，處否之極，泰道將至，故傾棄其否，以至通泰，故曰「傾否」。先塞後通，故後有喜慶，故曰「先否後喜」也。</p>',22)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
